mapper.select:
SELECT r.replyID AS replyId, r.commentID AS commentId, r.parentReplyID AS parentReplyId, r.userID AS userId, u.nickname AS nickname, u.imgUrl AS avatarUrl, u2.nickname AS replyToNickname, r.replyText AS replyText, r.likeCount AS likeCount, r.dislikeCount AS dislikeCount, r.gmtCreate AS gmtCreate FROM commentreplie r LEFT JOIN `user` u ON r.userID = u.userID LEFT JOIN commentreplie r2 ON r.parentReplyID = r2.replyID LEFT JOIN `user` u2 ON r2.userID = u2.userID WHERE r.enable = 1 AND r.commentID IN
#{cid}
ORDER BY r.gmtCreate ASC, r.replyID ASC
